/* ==========================================================================
   L'ÉCRIN - HAUTE GASTRONOMIE
   Master Design System & Styling Architecture
   Aesthetics: Minimalist Luxury, Monochromatic Slate, Architectural Precision
   CRITICAL CONSTRAINT: 100% SOLID COLORS ONLY - ZERO GRADIENTS
   ========================================================================== */

/* Google Fonts Imports */
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;0,700;1,400;1,600&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  /* Core Solid Color Palette - Strictly No Gradients */
  --bg-primary: #0C0D0E;
  --bg-secondary: #131517;
  --bg-tertiary: #1B1E21;
  --bg-card: #151719;
  --bg-card-hover: #1A1D20;
  --bg-overlay: rgba(12, 13, 14, 0.92);
  --bg-modal: #141618;

  /* Hairline Borders & Dividers */
  --border-subtle: #222529;
  --border-light: #2D3238;
  --border-accent: #C5A880;

  /* Typography Colors */
  --text-primary: #F4F1EA;
  --text-secondary: #9B9FA5;
  --text-muted: #6C7077;
  --text-inverted: #0C0D0E;

  /* Subtle Warm Accent (Solid Brass / Antique Gold) */
  --accent-gold: #C5A880;
  --accent-gold-hover: #D8BCA4;
  --accent-gold-dim: #26211B;
  --accent-gold-border: #3D352B;

  /* Status Solid Colors */
  --color-success: #2E7D32;
  --color-success-bg: #132415;
  --color-error: #D32F2F;
  --color-error-bg: #291212;

  /* Typography Tokens */
  --font-serif: 'Cormorant Garamond', Georgia, serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Layout Spacing */
  --container-max: 1240px;
  --container-narrow: 860px;
  --header-height: 80px;

  /* Transitions */
  --transition-fast: 0.2s ease;
  --transition-base: 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-slow: 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Base Reset & Box Sizing */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.65;
  background-color: var(--bg-primary);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
}

/* Typography Defaults */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 400;
  line-height: 1.2;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

h1 {
  font-size: clamp(2.5rem, 5vw, 4.2rem);
  letter-spacing: -0.02em;
}

h2 {
  font-size: clamp(2rem, 3.5vw, 3rem);
}

h3 {
  font-size: clamp(1.4rem, 2.2vw, 1.85rem);
}

h4 {
  font-size: 1.25rem;
}

p {
  color: var(--text-secondary);
  font-size: 1rem;
  line-height: 1.7;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button, input, select, textarea {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  background: none;
  border: none;
  outline: none;
}

ul, ol {
  list-style: none;
}

/* Container */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.container-narrow {
  width: 100%;
  max-width: var(--container-narrow);
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

/* ==========================================================================
   NAVIGATION & HEADER
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  left: 0;
  width: 100%;
  height: var(--header-height);
  background-color: rgba(12, 13, 14, 0.94);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-subtle);
  z-index: 1000;
  display: flex;
  align-items: center;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.brand-logo {
  display: flex;
  flex-direction: column;
  text-decoration: none;
}

.brand-title {
  font-family: var(--font-serif);
  font-size: 1.6rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-primary);
  font-weight: 500;
}

.brand-subtitle {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent-gold);
  margin-top: -2px;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 2.2rem;
}

.nav-link {
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-secondary);
  position: relative;
  padding: 0.4rem 0;
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--text-primary);
}

.nav-link.active {
  color: var(--accent-gold);
}

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--accent-gold);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 1.25rem;
}

.btn-reserve-nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.65rem 1.4rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-inverted);
  background-color: var(--accent-gold);
  border: 1px solid var(--accent-gold);
  border-radius: 0;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.btn-reserve-nav:hover {
  background-color: var(--accent-gold-hover);
  border-color: var(--accent-gold-hover);
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 32px;
  height: 32px;
  cursor: pointer;
  background: transparent;
  border: none;
  padding: 0;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 1.5px;
  background-color: var(--text-primary);
  transition: transform var(--transition-fast), opacity var(--transition-fast);
}

/* Mobile Drawer */
.mobile-nav-drawer {
  position: fixed;
  top: var(--header-height);
  left: 0;
  width: 100%;
  height: calc(100vh - var(--header-height));
  background-color: var(--bg-primary);
  border-top: 1px solid var(--border-subtle);
  padding: 2.5rem 2rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transform: translateY(-100%);
  opacity: 0;
  pointer-events: none;
  transition: transform var(--transition-base), opacity var(--transition-base);
  z-index: 999;
}

.mobile-nav-drawer.open {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.mobile-nav-link {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 0.75rem;
}

.mobile-nav-link.active {
  color: var(--accent-gold);
  border-color: var(--accent-gold);
}

.mobile-nav-footer {
  padding-top: 2rem;
  border-top: 1px solid var(--border-subtle);
}

/* ==========================================================================
   BUTTONS & BADGES (100% Solid Colors)
   ========================================================================== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  padding: 0.85rem 1.8rem;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all var(--transition-fast);
  border-radius: 0;
  text-align: center;
}

.btn-primary {
  background-color: var(--accent-gold);
  color: var(--text-inverted);
  border: 1px solid var(--accent-gold);
}

.btn-primary:hover {
  background-color: var(--accent-gold-hover);
  border-color: var(--accent-gold-hover);
}

.btn-outline {
  background-color: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-light);
}

.btn-outline:hover {
  background-color: var(--bg-tertiary);
  border-color: var(--accent-gold);
  color: var(--text-primary);
}

.btn-subtle {
  background-color: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-subtle);
}

.btn-subtle:hover {
  background-color: var(--border-subtle);
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.65rem;
  font-size: 0.68rem;
  font-family: var(--font-mono);
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background-color: var(--accent-gold-dim);
  color: var(--accent-gold);
  border: 1px solid var(--accent-gold-border);
}

.badge-neutral {
  background-color: var(--bg-tertiary);
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle);
}

.eyebrow {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent-gold);
  margin-bottom: 0.85rem;
}

/* ==========================================================================
   PAGE HEROES & BANNERS
   ========================================================================== */
.hero-editorial {
  position: relative;
  min-height: calc(100vh - var(--header-height));
  display: flex;
  align-items: center;
  padding: 4rem 0;
  border-bottom: 1px solid var(--border-subtle);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 4rem;
  align-items: center;
}

.hero-content {
  max-width: 620px;
}

.hero-title {
  margin-bottom: 1.5rem;
  line-height: 1.1;
}

.hero-desc {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 2.5rem;
  max-width: 520px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1.25rem;
  margin-bottom: 3.5rem;
}

.hero-meta-strip {
  display: flex;
  gap: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border-subtle);
}

.meta-item-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 0.25rem;
}

.meta-item-value {
  font-size: 0.95rem;
  color: var(--text-primary);
  font-weight: 500;
}

.hero-visual-frame {
  position: relative;
  border: 1px solid var(--border-light);
  padding: 10px;
  background-color: var(--bg-card);
}

.hero-visual-frame img {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  filter: contrast(102%) brightness(96%);
}

.hero-caption {
  position: absolute;
  bottom: 25px;
  left: 25px;
  right: 25px;
  background-color: var(--bg-primary);
  border: 1px solid var(--border-subtle);
  padding: 1rem 1.25rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.hero-caption-title {
  font-family: var(--font-serif);
  font-size: 1.1rem;
  color: var(--text-primary);
}

.hero-caption-sub {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--accent-gold);
  letter-spacing: 0.1em;
}

/* Page Header Standard */
.page-header {
  padding: 5rem 0 3.5rem;
  background-color: var(--bg-secondary);
  border-bottom: 1px solid var(--border-subtle);
  text-align: center;
}

.page-header-content {
  max-width: 720px;
  margin: 0 auto;
}

.page-header-title {
  margin-bottom: 1rem;
}

.page-header-desc {
  font-size: 1.1rem;
  color: var(--text-secondary);
}

/* ==========================================================================
   SECTIONS & LAYOUT BLOCKS
   ========================================================================== */
.section {
  padding: 6rem 0;
  border-bottom: 1px solid var(--border-subtle);
}

.section-alt {
  background-color: var(--bg-secondary);
}

.section-heading-wrap {
  margin-bottom: 3.5rem;
  text-align: center;
}

.section-heading-left {
  text-align: left;
  margin-bottom: 3.5rem;
}

.section-heading-title {
  margin-bottom: 0.75rem;
}

.section-heading-desc {
  max-width: 580px;
  margin: 0 auto;
  font-size: 1.05rem;
}

/* 3-Column Pillar Feature Grid */
.pillars-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.pillar-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  padding: 2.75rem 2rem;
  transition: transform var(--transition-base), border-color var(--transition-base);
  display: flex;
  flex-direction: column;
}

.pillar-card:hover {
  border-color: var(--accent-gold);
  background-color: var(--bg-card-hover);
}

.pillar-number {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--accent-gold);
  letter-spacing: 0.2em;
  margin-bottom: 1.5rem;
}

.pillar-title {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.pillar-text {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* Quote Feature Block */
.chef-statement-block {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 4rem;
  align-items: center;
}

.chef-statement-image {
  border: 1px solid var(--border-light);
  padding: 8px;
  background-color: var(--bg-card);
}

.chef-statement-image img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.chef-quote {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 2.3vw, 2.1rem);
  font-style: italic;
  line-height: 1.4;
  color: var(--text-primary);
  margin-bottom: 2rem;
}

.chef-attribution-name {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
}

.chef-attribution-role {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent-gold);
}

/* ==========================================================================
   ACCOLADES / METRICS BAR
   ========================================================================== */
.accolades-strip {
  padding: 3rem 0;
  border-bottom: 1px solid var(--border-subtle);
  background-color: var(--bg-secondary);
}

.accolades-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.accolade-item {
  padding: 1rem;
  border-right: 1px solid var(--border-subtle);
}

.accolade-item:last-child {
  border-right: none;
}

.accolade-num {
  font-family: var(--font-serif);
  font-size: 2.2rem;
  color: var(--accent-gold);
  line-height: 1.1;
  margin-bottom: 0.25rem;
}

.accolade-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

/* ==========================================================================
   MENU ARCHITECTURE (Page 2 & Components)
   ========================================================================== */
.menu-controls {
  margin-bottom: 3.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: center;
}

.menu-category-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem;
}

.menu-tab-btn {
  padding: 0.65rem 1.4rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  background-color: var(--bg-card);
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.menu-tab-btn:hover {
  color: var(--text-primary);
  border-color: var(--border-light);
}

.menu-tab-btn.active {
  background-color: var(--accent-gold);
  color: var(--text-inverted);
  border-color: var(--accent-gold);
}

.dietary-filters {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.dietary-chip {
  padding: 0.3rem 0.75rem;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background-color: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-subtle);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.dietary-chip:hover {
  border-color: var(--text-muted);
}

.dietary-chip.active {
  background-color: var(--bg-tertiary);
  border-color: var(--accent-gold);
  color: var(--accent-gold);
}

/* Menu Grid */
.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

.menu-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-subtle);
  padding: 2rem;
  transition: border-color var(--transition-base), transform var(--transition-base);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  position: relative;
}

.menu-card:hover {
  border-color: var(--border-light);
  transform: translateY(-2px);
}

.menu-card-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1.5rem;
  margin-bottom: 0.75rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--border-subtle);
}

.menu-dish-name {
  font-size: 1.35rem;
  color: var(--text-primary);
}

.menu-dish-price {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--accent-gold);
  white-space: nowrap;
}

.menu-dish-desc {
  font-size: 0.92rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 1.25rem;
}

.menu-dish-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-subtle);
}

.dish-tags {
  display: flex;
  gap: 0.4rem;
}

.dish-tag {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  padding: 0.15rem 0.45rem;
  background-color: var(--bg-tertiary);
  color: var(--text-muted);
  border: 1px solid var(--border-subtle);
}

.dish-action-hint {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent-gold);
